const siteRoot = new URL('../', document.currentScript.src);
'use strict';
const toggle=document.querySelector('#nav-toggle');
toggle?.addEventListener('click',()=>{const open=document.body.classList.toggle('nav-open');toggle.setAttribute('aria-expanded',String(open));});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.body.classList.remove('nav-open');toggle?.setAttribute('aria-expanded','false');}});
let indexPromise;const search=document.querySelector('#kb-search'),results=document.querySelector('#results');
const escapeHTML=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
search?.addEventListener('input',async()=>{const q=search.value.trim().toLowerCase();if(!q){results.innerHTML='';return;}try{indexPromise??=fetch(new URL('assets/search.json', siteRoot)).then(r=>{if(!r.ok)throw Error();return r.json()});const entries=await indexPromise;if(q!==search.value.trim().toLowerCase())return;const terms=q.split(/\s+/);const found=entries.filter(x=>terms.every(t=>(x.title+' '+x.text).toLowerCase().includes(t))).sort((a,b)=>{const score=x=>(x.title.toLowerCase().includes(q)?100:0)+(x.text.toLowerCase().includes(q)?50:0)+(x.url.includes('#')?5:0);return score(b)-score(a)}).slice(0,24);results.innerHTML=found.length?found.map(x=>{const lower=x.text.toLowerCase();const positions=terms.map(t=>lower.indexOf(t)).filter(p=>p>=0);const start=Math.max(0,(positions.length?Math.min(...positions):0)-45);const snippet=(start?'…':'')+x.text.slice(start,start+160);const context=x.context_url?`<a href="${escapeHTML(new URL(x.context_url,siteRoot).href)}"><small>Manual applicability and source</small></a>`:'';return `<a href="${escapeHTML(new URL(x.url, siteRoot).href)}">${escapeHTML(x.title)}<small>${escapeHTML(snippet)}…</small></a>${context}`}).join(''):'<p>No matching records. Try a part number, zone name, terminal, or PDF fault code.</p>';}catch{results.textContent='Search is unavailable. Use the index tree below.'}});
